// Кейс: .qa/tests/alerts/ALR-005.md (шаг 1) · план: .qa/e2e-app/specs/app.md (1.18)
// Только чтение: строки телефонов не открываются, ничего не меняется. Предусловие: второй телефон аккаунта подключён.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = '«חשבון» → «מכשירים»: в списке второй телефон «מכשיר נוסף · מקבל התרעות» #48f2b9 @iphone @app @prod-safe';

export default async function (app) {
  // 1. «חשבון» → «מכשירים».
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('מכשירים'), { what: 'строка «מכשירים» в «חשבון»' });
  await row.click();

  // 2. Список «הטלפונים בחשבון»: есть «מכשיר ראשי» и строка «מכשיר נוסף · מקבל התרעות».
  await app.waitFor(by.contains('הטלפונים בחשבון'), { timeout: 20000, what: 'список «הטלפונים בחשבון»' });
  const second = `(${by.contains('מכשיר נוסף')}) AND (name CONTAINS "מקבל התרעות" OR label CONTAINS "מקבל התרעות")`;
  await app.scrollTo(second, { max: 4, what: 'строка телефона «מכשיר נוסף · מקבל התרעות»' });
  const main = await app.findAll(by.contains('מכשיר ראשי'));
  assert(main.length >= 1, 'в списке есть и «מכשיר ראשי» (оба телефона аккаунта)');

  await app.restart();
}
